    case 3: month = 5; day = 31 - ctWeekday(ctDay(year, 5, 31)); break;
    case 4: month = 6; day = 19; break;
    case 5: month = 7; day = 4; break;
    case 6: month = 9; day = ctNthWeekday(year, 9, 0, 1); break;
