// Eligibility belongs to the start date. Thus an overnight stop is still due
// after the last selected weekday or date/holiday window has ended.
bool ctEligible(const CastleTekSchedule& item, int32_t startDay, int currentYear) {
  if (item.kind == 0) {
    if (!(item.weekdays & (1u << ctWeekday(startDay)))) return false;
    return !item.from || (startDay >= ctDay(item.from) && startDay <= ctDay(item.to));
  }
  if (item.kind != 3) return true;
  for (int year = currentYear - 2; year <= currentYear + 2; year++) {
    int32_t anchor = ctHolidayDay(year, item.holiday, item.observed);
    if (startDay >= anchor - item.before && startDay <= anchor + item.after) return true;
  }
  return false;
}
// Return one winning action: -1 means no action, 0 is explicit off, 1..250 a
// preset. Stops precede starts; holiday starts have final precedence. Array
// order breaks ties, matching WLED's single pending-preset behavior.
int ctScheduleAction(const CastleTekScheduleState& state, int year, int32_t today, int nowMinute,
                     int sunriseMinute, int sunsetMinute) {
  int action = -1;
  for (int pass = 0; pass < 3; pass++) {
    for (size_t i = 0; i < state.count; i++) {
      const CastleTekSchedule& item = state.items[i];
      if (!item.enabled) continue;
      bool paired = item.kind == 0 || item.kind == 3;
      bool holidaySolar = item.kind == 3 && item.solarWindow;
      if (pass == 0) {
        if (!paired) continue;
        int stop = holidaySolar ? sunriseMinute : item.stop;
        int32_t startDay = today - (holidaySolar || item.stop < item.start ? 1 : 0);
        if (stop >= 0 && nowMinute == stop && ctEligible(item, startDay, year)) action = item.stopPreset;
      } else {
        if ((item.kind == 3) != (pass == 2)) continue;
        int start = item.start;
        if (item.kind == 1 || item.kind == 2) {
          start = item.kind == 1 ? sunriseMinute : sunsetMinute;
          if (start < 0) continue;
          start = (start + item.offset + 1440) % 1440;
        } else if (holidaySolar) start = sunsetMinute;
        if (start >= 0 && nowMinute == start && ctEligible(item, today, year)) action = item.preset;
      }
    }
  }
  return action;
}
