  if (!ctScheduleAvailable || !ctSchedules.count || toki.getTimeSource() == TOKI_TS_NONE) return;
  int y = year(localTime);
  if (y < 1970 || y > 2099) return;
  uint32_t currentMinute = uint32_t(localTime) / 60;
  if (currentMinute == ctLastScheduleMinute) return;
  ctLastScheduleMinute = currentMinute;
  CT_SCHEDULE_LOCK();
  int action = ctScheduleAction(ctSchedules, y, ctDay(y, month(localTime), day(localTime)), hour(localTime) * 60 + minute(localTime),
                               sunrise ? hour(sunrise) * 60 + minute(sunrise) : -1,
                               sunset ? hour(sunset) * 60 + minute(sunset) : -1);
  CT_SCHEDULE_UNLOCK();
  if (action < 0) return;
  // applyPreset(0) unloads the playlist and clears an earlier queued legacy
  // preset. Zero is an explicit managed action only, never a native timer ID.
  applyPreset(uint8_t(action));
  if (action == 0 && bri) { toggleOnOff(); stateUpdated(CALL_MODE_DIRECT_CHANGE); }
